<template>
  <el-drawer :model-value="modelValue" title="写作实验室" size="min(1180px,96vw)" append-to-body @update:model-value="emit('update:modelValue',$event)" @open="loadAll">
    <div class="writing-boundary"><b>写作研究边界</b><span>蒸馏的是可操作风格规律，不复制原文观点，也不冒充原作者；私密或付费语料须确认处理权限。</span></div>
    <el-tabs v-model="mode" class="writing-tabs">
      <el-tab-pane label="写作 DNA" name="dna">
        <div class="dna-layout">
          <aside class="dna-sidebar">
            <header><b>DNA 项目</b><el-button size="small" plain @click="creating=!creating">{{ creating?'收起':'新建' }}</el-button></header>
            <div v-if="creating" class="profile-form">
              <el-input v-model="profileForm.name" placeholder="项目名称，例如：我的评论写作" />
              <el-input v-model="profileForm.target_author" placeholder="作者或账号（可选）" />
              <el-select v-model="profileForm.book_ids" multiple collapse-tags filterable remote :remote-method="searchBooks" :loading="booksLoading" placeholder="搜索并选择至少20篇完整文章">
                <el-option v-for="book in bookOptions" :key="book.id" :label="book.title" :value="book.id" />
              </el-select>
              <span :class="['corpus-count',{ready:profileForm.book_ids.length>=20}]">{{ profileForm.book_ids.length }}/20 篇最低语料</span>
              <el-checkbox v-model="profileForm.rights_acknowledged">我确认有权处理所选文章</el-checkbox>
              <el-button type="primary" :disabled="!canDistill" :loading="submitting" @click="createProfile">开始蒸馏</el-button>
            </div>
            <button v-for="profile in profiles" :key="profile.id" :class="['profile-row',{active:selectedProfileId===profile.id}]" @click="openProfile(profile.id)">
              <span><b>{{ profile.name }}</b><small>{{ profile.corpus_count }}篇 · v{{ profile.current_version }}</small></span>
              <el-tag size="small" :type="statusType(profile.status)">{{ statusText(profile.status) }}</el-tag>
            </button>
            <StudyEmptyState v-if="!profiles.length&&!creating" compact title="尚无 Writing DNA" description="从至少20篇完整文章建立第一版。" />
          </aside>
          <main class="dna-main">
            <StudyEmptyState v-if="!profileDetail" title="选择或新建 DNA 项目" description="系统会分别保存语言、结构、选题与认知、视觉和整合 DNA，并保留每次完善版本。" />
            <template v-else>
              <div class="profile-head"><div><span>Writing DNA · v{{ profileDetail.current_version }}</span><h3>{{ profileDetail.name }}</h3><p>{{ profileDetail.corpus_count }} 篇完整文章 · {{ profileDetail.target_author||'未指定作者' }}</p></div><div class="version-tools"><el-select v-if="profileDetail.revisions?.length" v-model="selectedRevisionId" size="small" aria-label="查看历史版本"><el-option v-for="revision in profileDetail.revisions" :key="revision.id" :label="`查看 v${revision.version}`" :value="revision.id" /></el-select><el-select v-if="profileDetail.revisions?.length>1" v-model="compareRevisionId" clearable size="small" placeholder="比较版本" aria-label="比较历史版本"><el-option v-for="revision in profileDetail.revisions.filter(item=>item.id!==selectedRevisionId)" :key="revision.id" :label="`比较 v${revision.version}`" :value="revision.id" /></el-select><el-tag :type="statusType(profileDetail.status)">{{ statusText(profileDetail.status) }}</el-tag></div></div>
              <el-alert v-if="profileDetail.error_msg" type="error" :title="profileDetail.error_msg" show-icon />
              <template v-if="activeRevision">
                <div class="quality-strip"><span><b>{{ activeRevision.quality?.article_count||profileDetail.corpus_count }}</b>文章</span><span><b>{{ activeRevision.quality?.structure_type_count||'—' }}</b>结构类型</span><span><b>{{ activeRevision.quality?.cognitive_claim_count||'—' }}</b>认知命题</span><span><b>{{ activeRevision.quality?.visual_sample_count||0 }}</b>视觉样本</span></div>
                <div v-if="activeRevision.quality?.limitations?.length" class="quality-limit"><b>本版限制</b><span>{{ activeRevision.quality.limitations.join('；') }}</span></div>
                <section v-if="comparisonRevision" class="revision-compare"><header><b>v{{ activeRevision.version }} 与 v{{ comparisonRevision.version }}</b><el-button text size="small" @click="compareRevisionId=null">结束比较</el-button></header><div><span>语料 {{ activeRevision.quality?.article_count||0 }} / {{ comparisonRevision.quality?.article_count||0 }}</span><span>结构类型 {{ activeRevision.quality?.structure_type_count||'—' }} / {{ comparisonRevision.quality?.structure_type_count||'—' }}</span><span>认知命题 {{ activeRevision.quality?.cognitive_claim_count||'—' }} / {{ comparisonRevision.quality?.cognitive_claim_count||'—' }}</span></div><el-collapse><el-collapse-item title="并排核对整合 DNA" name="compare"><div class="compare-text"><article v-html="renderMarkdown(activeRevision.writing_dna)"/><article v-html="renderMarkdown(comparisonRevision.writing_dna)"/></div></el-collapse-item></el-collapse></section>
                <details class="corpus-audit"><summary>核对语料清单 · {{ profileDetail.corpus_manifest?.length||0 }} 篇</summary><div v-if="removeBookIds.length" class="corpus-pending">下一版将排除 {{ removeBookIds.length }} 篇；至少仍需保留 20 篇。</div><div class="corpus-rows"><div v-for="item in profileDetail.corpus_manifest" :key="item.book_id" :class="{removed:removeBookIds.includes(item.book_id)}"><span><b>{{ item.title }}</b><small>{{ item.file_type?.toUpperCase() }} · {{ item.chars?.toLocaleString() }} 字符</small></span><div><el-tag v-if="item.image_count" size="small" effect="plain">图像 {{ item.image_count }}</el-tag><el-button text size="small" @click="toggleCorpusRemoval(item.book_id)">{{ removeBookIds.includes(item.book_id)?'恢复':'下一版排除' }}</el-button></div></div></div></details>
                <el-collapse accordion class="artifact-list">
                  <el-collapse-item title="Writing-DNA（整合）" name="all"><article v-html="renderMarkdown(activeRevision.writing_dna)" /></el-collapse-item>
                  <el-collapse-item title="语言 DNA" name="language"><article v-html="renderMarkdown(activeRevision.language_dna)" /></el-collapse-item>
                  <el-collapse-item title="文章结构模板" name="structure"><article v-html="renderMarkdown(activeRevision.structure_patterns)" /></el-collapse-item>
                  <el-collapse-item title="写作视角与认知框架" name="cognitive"><article v-html="renderMarkdown(activeRevision.cognitive_framework)" /></el-collapse-item>
                  <el-collapse-item title="视觉风格指南" name="visual"><article v-html="renderMarkdown(activeRevision.visual_style_guide)" /></el-collapse-item>
                </el-collapse>
              </template>
              <section class="refine-panel"><header><b>持续完善</b><small>补充、排除文章或写下修正意见，会生成新版本并保留旧版。</small></header><el-select v-model="refineBooks" multiple collapse-tags filterable remote :remote-method="searchBooks" :loading="booksLoading" placeholder="补充语料（可选）"><el-option v-for="book in bookOptions" :key="book.id" :label="book.title" :value="book.id" /></el-select><el-input v-model="refineFeedback" type="textarea" :rows="2" placeholder="例如：减少对早期文章的权重；视觉分析补充截图型证据。" /><el-button :disabled="!refineBooks.length&&!removeBookIds.length&&!refineFeedback.trim()" :loading="submitting" @click="refineProfile">生成下一版本</el-button></section>
              <section class="imitate-panel"><header><b>独立仿写与输出</b><small>每次会读取全部 DNA 产物和5篇相近原文，只校准写法，不搬用原文内容。</small></header><div class="imitate-grid"><el-input v-model="imitateForm.topic" placeholder="新文章题目或议题" /><el-select v-model="imitateForm.genre"><el-option label="深度文章" value="深度文章"/><el-option label="评论" value="评论"/><el-option label="短评" value="短评"/><el-option label="综述" value="综述"/></el-select><el-input-number v-model="imitateForm.length" :min="300" :max="12000" :step="100" /></div><el-input v-model="imitateForm.brief" type="textarea" :rows="2" placeholder="本次立场、素材边界和发布场景"/><el-button type="primary" :loading="generating" :disabled="!imitateForm.topic.trim()" @click="runImitation">生成独立新作</el-button>
                <div v-if="currentOutput?.kind==='imitation'" class="writing-result"><header><b>{{ currentOutput.title }}</b><div><el-button v-if="!editingOutput" text size="small" @click="beginEditOutput">编辑</el-button><el-button v-else text size="small" @click="cancelEditOutput">取消</el-button><a :href="writingOutputDownloadUrl(currentOutput.id)">下载 Word</a></div></header><template v-if="editingOutput"><el-input v-model="draftTitle" maxlength="255" /><el-input v-model="draftText" type="textarea" :rows="18" maxlength="200000" show-word-limit /><el-button type="primary" :loading="savingOutput" @click="saveOutput">保存并重新生成 Word</el-button></template><article v-else v-html="renderMarkdown(currentOutput.output_text)" /></div>
              </section>
            </template>
          </main>
        </div>
      </el-tab-pane>
      <el-tab-pane label="去 AI 味" name="clean">
        <div class="clean-layout">
          <section class="clean-input">
            <header><b>白名单式最小改写</b><small>只处理11类可定位痕迹；结构、事实、数字、引语、链接和限定词保持不变。</small></header>
            <el-select v-model="cleanProfileId" clearable placeholder="可选：使用某个语言 DNA 判断原语体"><el-option v-for="profile in readyProfiles" :key="profile.id" :label="profile.name" :value="profile.id" /></el-select>
            <el-input v-model="cleanText" type="textarea" :rows="16" maxlength="120000" show-word-limit placeholder="粘贴需要处理的文本" />
            <div class="clean-actions"><el-button type="primary" :loading="cleaning" :disabled="!cleanText.trim()" @click="runTextClean">处理文本</el-button><el-upload :show-file-list="false" :auto-upload="false" accept=".docx" :on-change="runDocxClean"><el-button :loading="cleaning">导入 Word 并输出 Word</el-button></el-upload></div>
          </section>
          <section class="clean-output">
            <header><b>输出与审计</b><a v-if="currentOutput?.download_ready" :href="writingOutputDownloadUrl(currentOutput.id)">下载 Word</a></header>
            <StudyEmptyState v-if="!currentOutput||currentOutput.kind!=='ai_tone'" compact title="尚无处理结果" description="未命中白名单的文字会原样保留。" />
            <template v-else><div class="audit-strip"><span>候选 {{ outputChanges.length }} 处</span><span>已选择 {{ acceptedIndexes.length }} 处</span><span>拒绝 {{ currentOutput.audit?.rejected?.length||0 }} 处越界改写</span></div><div v-if="outputChanges.length" class="change-review"><header><b>逐条决定是否采用</b><el-checkbox :model-value="acceptedIndexes.length===outputChanges.length" @change="toggleAllChanges">全选</el-checkbox></header><label v-for="(change,index) in outputChanges" :key="`${change.id}-${index}`"><el-checkbox v-model="acceptedIndexes" :value="index"/><span><del>{{ change.old }}</del><ins>{{ change.new||'（删除）' }}</ins><small>规则 {{ change.rule_ids?.join('、') }}</small></span></label><el-button type="primary" plain :loading="reviewing" @click="applyReviewedChanges">按选择重新生成 Word</el-button></div><el-input v-model="currentOutput.output_text" type="textarea" :rows="12" readonly /></template>
          </section>
        </div>
      </el-tab-pane>
      <el-tab-pane label="写作输出" name="outputs">
        <div class="output-layout">
          <aside class="output-history"><header><b>最近输出</b><el-button text size="small" @click="loadOutputs">刷新</el-button></header><button v-for="item in outputs" :key="item.id" :class="{active:currentOutput?.id===item.id}" @click="openOutput(item.id)"><span><b>{{ item.title }}</b><small>{{ item.kind==='imitation'?'独立新作':'去 AI 味' }} · {{ item.output_length?.toLocaleString() }} 字</small></span><time>{{ formatDate(item.created_at) }}</time></button><StudyEmptyState v-if="!outputs.length" compact title="尚无写作输出" description="生成或处理稿件后会保存在这里。"/><el-pagination v-if="outputTotal>20" small layout="prev, pager, next" :total="outputTotal" :page-size="20" @current-change="loadOutputs"/></aside>
          <main class="output-detail"><StudyEmptyState v-if="!currentOutput" title="选择一条输出" description="正文按需加载，不在列表中返回完整内容。"/><template v-else><header><div><span>{{ currentOutput.kind==='imitation'?'独立新作':'白名单去 AI 味' }}</span><h3>{{ currentOutput.title }}</h3></div><div><el-button v-if="currentOutput.kind==='imitation'&&!editingOutput" plain @click="beginEditOutput">编辑</el-button><el-button v-if="currentOutput.kind==='ai_tone'" plain @click="mode='clean'">逐条审阅</el-button><a v-if="currentOutput.download_ready" :href="writingOutputDownloadUrl(currentOutput.id)">下载 Word</a></div></header><div v-if="currentOutput.kind==='ai_tone'&&outputChanges.length" class="history-audit">{{ outputChanges.length }} 项候选修改 · 已采用 {{ currentOutput.audit?.accepted_indexes?.length ?? outputChanges.length }} 项 · 规则 {{ (currentOutput.audit?.rules||[]).join('、') }}</div><template v-if="editingOutput"><el-input v-model="draftTitle"/><el-input v-model="draftText" type="textarea" :rows="22" maxlength="200000" show-word-limit/><div class="edit-actions"><el-button @click="cancelEditOutput">取消</el-button><el-button type="primary" :loading="savingOutput" @click="saveOutput">保存并重新生成 Word</el-button></div></template><article v-else class="markdown-body" v-html="renderMarkdown(currentOutput.output_text)"/></template></main>
        </div>
      </el-tab-pane>
    </el-tabs>
  </el-drawer>
</template>

<script setup>
import { computed, ref } from 'vue'
import { ElMessage } from 'element-plus'
import { listBooks, listWritingProfiles, getWritingProfile, createWritingProfile, refineWritingProfile, imitateWriting, cleanAiToneText, cleanAiToneDocx, listWritingOutputs, getWritingOutput, updateWritingOutput, reviewWritingOutput, writingOutputDownloadUrl, subscribeTask } from '../api'
import { notifyTaskSubmitted } from '../stores/taskCenter'
import { renderMarkdown } from '../utils/markdown'
import StudyEmptyState from './StudyEmptyState.vue'

defineProps({ modelValue:Boolean })
const emit=defineEmits(['update:modelValue'])
const mode=ref('dna'),profiles=ref([]),profileDetail=ref(null),selectedProfileId=ref(null),selectedRevisionId=ref(null),compareRevisionId=ref(null),creating=ref(false),submitting=ref(false),generating=ref(false),cleaning=ref(false)
const bookOptions=ref([]),booksLoading=ref(false),refineBooks=ref([]),removeBookIds=ref([]),refineFeedback=ref(''),cleanProfileId=ref(null),cleanText=ref(''),currentOutput=ref(null)
const outputs=ref([]),outputTotal=ref(0),acceptedIndexes=ref([]),reviewing=ref(false),editingOutput=ref(false),savingOutput=ref(false),draftTitle=ref(''),draftText=ref('')
const profileForm=ref({name:'',target_author:'',book_ids:[],rights_acknowledged:false})
const imitateForm=ref({topic:'',genre:'深度文章',length:1800,brief:''})
const readyProfiles=computed(()=>profiles.value.filter(p=>p.status==='ready'))
const activeRevision=computed(()=>profileDetail.value?.revisions?.find(item=>item.id===selectedRevisionId.value)||profileDetail.value?.revisions?.[0]||null)
const comparisonRevision=computed(()=>profileDetail.value?.revisions?.find(item=>item.id===compareRevisionId.value)||null)
const outputChanges=computed(()=>Array.isArray(currentOutput.value?.audit?.changes)?currentOutput.value.audit.changes:[])
const canDistill=computed(()=>profileForm.value.name.trim()&&profileForm.value.book_ids.length>=20&&profileForm.value.rights_acknowledged)
const statusText=s=>({pending:'排队中',running:'蒸馏中',ready:'可使用',failed:'需重试'}[s]||s)
const statusType=s=>({ready:'success',failed:'danger',running:'warning',pending:'info'}[s]||'info')
const searchBooks=async(q='')=>{booksLoading.value=true;try{const r=await listBooks({status:'ready',q:q.trim()||undefined,page_size:40});const selected=bookOptions.value.filter(b=>profileForm.value.book_ids.includes(b.id)||refineBooks.value.includes(b.id));bookOptions.value=[...new Map([...selected,...r.items].map(b=>[b.id,b])).values()]}finally{booksLoading.value=false}}
const loadProfiles=async()=>{profiles.value=(await listWritingProfiles()).items||[]}
const openProfile=async id=>{selectedProfileId.value=id;profileDetail.value=await getWritingProfile(id);selectedRevisionId.value=profileDetail.value.revisions?.[0]?.id||null;compareRevisionId.value=null;removeBookIds.value=[]}
const loadOutputs=async(page=1)=>{const result=await listWritingOutputs({page,page_size:20});outputs.value=result.items||[];outputTotal.value=result.total||0}
const loadAll=async()=>{await Promise.all([loadProfiles(),searchBooks(''),loadOutputs()]);if(selectedProfileId.value)await openProfile(selectedProfileId.value)}
const followTask=(taskId,profileId)=>{notifyTaskSubmitted();subscribeTask(taskId,()=>{}).then(async()=>{await loadProfiles();await openProfile(profileId)}).catch(()=>loadProfiles())}
const createProfile=async()=>{submitting.value=true;try{const r=await createWritingProfile(profileForm.value);creating.value=false;await loadProfiles();await openProfile(r.profile_id);followTask(r.task_id,r.profile_id);ElMessage.success('蒸馏已进入全局任务中心')}catch(e){ElMessage.error(e.message)}finally{submitting.value=false}}
const toggleCorpusRemoval=id=>{removeBookIds.value=removeBookIds.value.includes(id)?removeBookIds.value.filter(value=>value!==id):[...removeBookIds.value,id]}
const refineProfile=async()=>{submitting.value=true;try{const r=await refineWritingProfile(selectedProfileId.value,{book_ids:refineBooks.value,remove_book_ids:removeBookIds.value,feedback:refineFeedback.value});refineBooks.value=[];removeBookIds.value=[];refineFeedback.value='';followTask(r.task_id,r.profile_id);ElMessage.success('新版本已提交，旧版本会保留')}catch(e){ElMessage.error(e.message)}finally{submitting.value=false}}
const prepareOutput=row=>{currentOutput.value=row;editingOutput.value=false;draftTitle.value=row?.title||'';draftText.value=row?.output_text||'';const saved=row?.audit?.accepted_indexes;acceptedIndexes.value=Array.isArray(saved)?[...saved]:outputChanges.value.map((_,index)=>index)}
const runImitation=async()=>{generating.value=true;try{prepareOutput(await imitateWriting(selectedProfileId.value,imitateForm.value));await loadOutputs();ElMessage.success('独立新作与 Word 已生成')}catch(e){ElMessage.error(e.message)}finally{generating.value=false}}
const runTextClean=async()=>{cleaning.value=true;try{prepareOutput(await cleanAiToneText({text:cleanText.value,title:'去 AI 味稿件',profile_id:cleanProfileId.value||null}));await loadOutputs();ElMessage.success('候选改写已生成，请逐条审阅')}catch(e){ElMessage.error(e.message)}finally{cleaning.value=false}}
const runDocxClean=async file=>{cleaning.value=true;try{prepareOutput(await cleanAiToneDocx(file.raw,cleanProfileId.value));await loadOutputs();ElMessage.success('Word 候选改写已生成，请逐条审阅')}catch(e){ElMessage.error(e.message)}finally{cleaning.value=false}}
const toggleAllChanges=value=>{acceptedIndexes.value=value?outputChanges.value.map((_,index)=>index):[]}
const applyReviewedChanges=async()=>{reviewing.value=true;try{prepareOutput(await reviewWritingOutput(currentOutput.value.id,acceptedIndexes.value));await loadOutputs();ElMessage.success('已按人工选择重新生成 Word')}catch(e){ElMessage.error(e.message)}finally{reviewing.value=false}}
const beginEditOutput=()=>{draftTitle.value=currentOutput.value?.title||'';draftText.value=currentOutput.value?.output_text||'';editingOutput.value=true}
const cancelEditOutput=()=>{editingOutput.value=false}
const saveOutput=async()=>{if(!draftTitle.value.trim()||!draftText.value.trim())return ElMessage.warning('标题和正文不能为空');savingOutput.value=true;try{prepareOutput(await updateWritingOutput(currentOutput.value.id,{title:draftTitle.value,output_text:draftText.value}));await loadOutputs();ElMessage.success('稿件和 Word 已更新')}catch(e){ElMessage.error(e.message)}finally{savingOutput.value=false}}
const openOutput=async id=>{try{prepareOutput(await getWritingOutput(id))}catch(e){ElMessage.error(e.message)}}
const formatDate=value=>value?new Date(value).toLocaleDateString('zh-CN'):'—'
</script>

